from __future__ import annotations


_REJECT = (
    "Reject Transcription/Translation (no subtitles), VideoAnalysis/IntakeVideo/"
    "StyleTransfer/VideoExtend/Highlight (no video uploaded), "
    "Narration/Illustration/Narrator (not a slideshow / illustrated-storytelling format)."
)


def _make(theme, arc, scenes, settings, aesthetic, bgm, ambience):
    """8-step chain. cinematic + music + ambience."""
    return {
        "rationale": (
            f"{theme} mini-drama from a text brief + {bgm} BGM + {ambience} ambient bed. "
            f"StoryAgent drafts the {arc} blueprint. ScreenplayAgent breaks it into "
            f"{scenes} scenes. KeyFrameAgent plans keyframes for the {settings} settings "
            "from text alone. VideoAgent assembles the multi-shot film. MusicAgent "
            f"composes the {bgm} score. AmbienceAgent generates the {ambience} ambient "
            "bed. AudioMixAgent layers both under the dialogue+foley. CompositorAgent "
            "muxes the final mp4. " + _REJECT
        ),
        "intents": [
            f"Draft the {theme} story blueprint — {arc} arc.",
            f"Decompose the {arc} arc into {scenes} scenes.",
            f"Plan keyframes for the {settings} settings; text-only generation, no reference images supplied.",
            f"Render per-shot clips preserving {aesthetic} visual continuity.",
            f"Compose the {bgm} BGM the user requested, matching the {aesthetic} register.",
            f"Generate the {ambience} ambient atmosphere as the audio bed.",
            f"Layer the {bgm} BGM and {ambience} ambient bed under the clip's baked dialogue+foley track into one final mixed wav.",
            f"Composite the final {aesthetic} mini-drama mp4 with mixed audio and inter-shot transitions.",
        ],
    }


